import{SHATTERED_NATIVE_PROFILE as DATA}from'./shattered-adapter-data.js';
const BASE=0x08000000,cache=new WeakMap(),hex=b=>Array.from(b,v=>v.toString(16).padStart(2,'0')).join(''),raw=h=>Uint8Array.from(h.match(/../g)||[],v=>parseInt(v,16));const guards=DATA.guards.map(g=>({...g,data:raw(g.bytes)}));
export function shatteredAdapter(reader){if(cache.has(reader))return cache.get(reader);const valid=reader.engine==='frlg'&&guards.every(g=>reader.valid(g.at,g.data.length)&&g.data.every((v,i)=>reader.bytes[g.at+i]===v));const result=valid?DATA:null;cache.set(reader,result);return result;}
export function describeShatteredCall(reader,node){const p=shatteredAdapter(reader);if(!p)return null;if([8,9,10,11].includes(node.code)){const indexArg=node.code>=10?1:0,index=node.args[indexArg].value;if(index>=p.standardNames.length)return null;return{kind:'standard-script',name:p.standardNames[index],entry:reader.ptr(p.standardTable+index*4),index,indexArg,support:'script graph'};}if([37,38].includes(node.code)){const index=node.args[node.code===38?1:0].value;if(index>=p.specialCount)return null;return{kind:'special',name:p.specialNames[index]||'Extended engine special '+index,entry:reader.u32(p.specialTable+index*4),index,support:p.specialNames[index]?'stock table identity; native implementation':'unresolved native implementation'};}if(node.name==='callnative'||node.name==='gotonative'){const ptr=node.args.find(a=>a.kind==='native')?.value;if(ptr===undefined)return null;const row=p.functions[ptr&~1];if(!row||!reader.valid((ptr&~1)-BASE,row.size)||raw(row.bytes).some((v,i)=>reader.bytes[(ptr&~1)-BASE+i]!==v))return null;return{kind:'shattered-native',name:row.name,entry:ptr,inputs:row.inputs,support:row.sourceMatch};}return null;}
export function validateShatteredCallArgs(reader,node,args){const p=shatteredAdapter(reader);if(!p)return;if([8,9,10,11].includes(node.code)&&args[node.code>=10?1:0]>=p.standardNames.length)throw Error('This Shattered standard-script ID is outside the verified table.');if([37,38].includes(node.code)&&args[node.code===38?1:0]>=p.specialCount)throw Error('This Shattered special ID is outside the verified table.');}
function ascii(reader,ptr){if(ptr<512||!reader.valid(ptr))throw Error('Invalid Shattered string pointer.');let text='';for(let i=0;i<1024&&reader.valid(ptr+i);i++){const c=reader.u8(ptr+i);if(!c)return text;if(c<32||c>126)throw Error('Unsupported native ASCII string.');text+=String.fromCharCode(c);}throw Error('Native string has no terminator.');}
export function readShatteredRecord(reader,table,id){const p=shatteredAdapter(reader),t=p?.tables[table];if(!t||!Number.isInteger(id)||id<0||id>=t.count)throw Error('No verified Shattered native data record.');const at=t.at+id*t.stride,bytes=reader.bytes.slice(at,at+t.stride),row={table,id,at,original:hex(bytes)},strings=[];const text=(field,offset)=>{const value=ascii(reader,reader.ptr(at+offset));row[field]=value;strings.push(value);};if(table==='classes'){text('name',0);text('description',4);row.stats=Array.from(bytes.slice(8,14));row.types=Array.from(bytes.slice(14,16));row.abilities=Array.from(bytes.slice(16,18));row.stage=bytes[18];row.a=bytes[19];row.b=bytes[20];}else if(table==='paths'){row.courses=[reader.u16(at),reader.u16(at+2)];text('name',4);text('description',8);}else if(table==='learnsets'){row.classId=bytes[0];row.level=bytes[1];row.move=reader.u16(at+2);}else{text('name',0);text('description',4);row.move=reader.u16(at+8);row.defense=bytes[10];row.speedPenalty=bytes[11];row.resistType=bytes[12];row.ability=bytes[13];row.price=bytes[14];}row.original+='|'+JSON.stringify(strings);return row;}
const int=(v,min,max,label)=>{if(!Number.isInteger(v)||v<min||v>max)throw Error(label+' must be '+min+'–'+max+'.');return v;};
export function validateShatteredDataPatch(reader,patch){const base=readShatteredRecord(reader,patch?.table,patch?.id);if(patch.original!==base.original||!patch.values||typeof patch.values!=='object'||Array.isArray(patch.values))throw Error('Shattered data changed from its original snapshot.');const fields=patch.table==='classes'?['name','description','stats','types','abilities']:patch.table==='paths'?['courses']:patch.table==='learnsets'?['level','move']:['name','description','move','defense','speedPenalty','resistType','ability','price'];for(const k of Object.keys(patch.values))if(!fields.includes(k))throw Error('This native field is not editable: '+k);const v={...base,...patch.values};for(const k of['name','description'])if(Object.hasOwn(patch.values,k)){if(typeof v[k]!=='string'||!v[k].length||v[k].length>base[k].length||!/^[\x20-\x7e]+$/.test(v[k]))throw Error(k+' must use printable ASCII and fit its original '+base[k].length+' characters.');}if(patch.table==='classes'){for(const[k,n,min,max]of[['stats',6,1,255],['types',2,0,23],['abilities',2,0,255]]){if(!Array.isArray(v[k])||v[k].length!==n)throw Error('Invalid class '+k);v[k].forEach(a=>int(a,min,max,k));}if(v.types.some(t=>t>=18&&t!==23))throw Error('Internal blank type IDs are not class types.');}else if(patch.table==='paths'){if(!patch.id)throw Error('The empty trial path is reserved.');if(!Array.isArray(v.courses)||v.courses.length!==2)throw Error('A trial needs two course moves.');v.courses.forEach(n=>int(n,1,990,'Course move'));}else if(patch.table==='learnsets'){int(v.level,1,100,'Level');int(v.move,1,990,'Move');}else{int(v.move,0,990,'Move');for(const k of['defense','speedPenalty','resistType','ability','price'])int(v[k],0,255,k);if(v.resistType!==255&&(v.resistType>17&&v.resistType!==23))throw Error('Use a valid native resist type or 255 for none.');}return{base,value:v};}
export function installShatteredDataEdits(reader,edits,output){const entries=Object.entries(edits||{});if(!entries.length)return[];if(!shatteredAdapter(reader))throw Error('This ROM does not match the verified Shattered native-code adapter.');const planned=[];for(const[key,patch]of entries){if(key!==patch.table+':'+patch.id)throw Error('Shattered native record identity mismatch.');const{base,value}=validateShatteredDataPatch(reader,patch),t=DATA.tables[patch.table],bytes=reader.bytes.slice(base.at,base.at+t.stride);if(bytes.some((v,i)=>output.bytes[base.at+i]!==v))throw Error('Shattered data overlaps another export edit.');const v=new DataView(bytes.buffer),strings=[];if(patch.table==='classes'){bytes.set(value.stats,8);bytes.set(value.types,14);bytes.set(value.abilities,16);strings.push(['name',0],['description',4]);}else if(patch.table==='paths'){v.setUint16(0,value.courses[0],true);v.setUint16(2,value.courses[1],true);}else if(patch.table==='learnsets'){bytes[1]=value.level;v.setUint16(2,value.move,true);}else{v.setUint16(8,value.move,true);for(const[k,off]of[['defense',10],['speedPenalty',11],['resistType',12],['ability',13],['price',14]])bytes[off]=value[k];strings.push(['name',0],['description',4]);}planned.push({base,value,bytes,strings});}for(const item of planned){const v=new DataView(item.bytes.buffer);for(const[field,off]of item.strings)if(item.value[field]!==item.base[field]){const text=Uint8Array.from([...item.value[field]].map(c=>c.charCodeAt(0)).concat(0)),at=output.allocate(text,'Shattered '+item.base.table+' '+field);v.setUint32(off,BASE+at,true);}output.write(item.base.at,item.bytes);}for(const item of planned)if(item.bytes.some((v,i)=>output.bytes[item.base.at+i]!==v))throw Error('Shattered data readback failed.');return[entries.length+' Shattered native class/trial/learnset/gear records verified and applied.'];}
export function boundShatteredInputs(graph,node){if(!node.adapter?.inputs?.length)return[];const incoming=new Map();for(const n of Object.values(graph.nodes))for(const e of n.edges||[]){if(!incoming.has(e.to))incoming.set(e.to,[]);incoming.get(e.to).push(n);}return node.adapter.inputs.map(input=>{let at=node.at;for(let n=0;n<12;n++){const prev=incoming.get(at);if(prev?.length!==1)break;const p=prev[0];if(p.end!==at||p.edges.length!==1)break;if(p.name==='setvar'&&p.args[0].value===input.variable)return{...input,assignment:p.at,index:1};if(!['setvar','compare_var_to_value','compare_var_to_var','checkflag'].includes(p.name))break;at=p.at;}return{...input,assignment:null};});}
